#define ZOOM 10.0f
#define RADIUS 0.4f
#define BASE_JITTER ((0.5f - RADIUS) * 2.0f)
#define SAFE_JITTER vec2(BASE_JITTER + 0.13333f, BASE_JITTER)
#define JITTER SAFE_JITTER

uvec2 uhash22(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uvec2 h = uvec2(1190494759u, 2147483647u);
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// 2 outputs, 2 inputs
vec2 hash22(vec2 src) {
    uvec2 h = uhash22(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0f;
}

vec2 idk(uvec2 cell_floor) {
    vec2 h = hash22(vec2(cell_floor));
    return h;//pow(vec2(2), h * 10.0f - 10.0f);
}

vec2 idk2(uvec2 cell_floor) {
    return vec2(cell_floor.x & 1u);
}

void mainImage( out vec4 colour, in vec2 coord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 cell = (coord / iResolution.y * ZOOM);

    uvec2 cell_floor = uvec2(floor(cell));

    cell.y += float(cell_floor) * 0.5f;

    vec2 cell_uv = fract(cell);

    vec2 centre = vec2(0.5f) + idk(uvec2(floor(cell))) * JITTER;

    float d = -(distance(cell_uv, centre) - RADIUS);

    vec2 ncell1 = vec2(cell.x - 1.0f, cell.y - 0.5f);
    vec2 nc1 = vec2(-0.5f, 0.5f) + idk(uvec2(floor(ncell1))) * JITTER;
    float nd1 = -(distance(fract(ncell1), nc1) - RADIUS);

    vec2 ncell2 = vec2(cell.x, cell.y - 1.0f);
    vec2 nc2 = vec2(0.5f, -0.5f) + idk(uvec2(floor(ncell2))) * JITTER;
    float nd2 = -(distance(fract(ncell2), nc2) - RADIUS);

    float f = max(max(d, nd1), nd2);

    float border = 1.0f - (sign(f) - sign(f - 0.07f));
    float point = 1.0f - (sign(f - (RADIUS - 0.1f)));

    // Output to screen
    colour = vec4(min(point, border));
}
